import {
  boxPaint,
  centredText,
  DASHED,
  DETAIL,
  directionOf,
  EDGE_WIDTH,
  endText,
  finish,
  LABEL,
  labelSvg,
  layered,
  lineSvg,
  markerAttribute,
  markerDef,
  markerLength,
  rectSvg,
  reversed,
  strokeSvg,
  TEXT,
