      y += rows + 2;
    }

    if (isStacked) {
      top = y + 1;
    }
  });

  return d.finish(
    `Kanban${title === "" ? "" : ` ${title}`}: ${columns
      .map((column) => `${column.name} ${column.cards.map((card) => card.text).join(", ")}`)
      .join("; ")}`,
    ctx,
  );
}

